use std::{env,fs};
#[derive(Clone,Copy,PartialEq,Eq,Debug)]enum P{O,A(i64,i64)}
fn r(x:i64)->i64{x.rem_euclid(61)}fn inv(x:i64)->i64{assert_ne!(r(x),0);let(mut a,mut b,mut u,mut v)=(61,r(x),0,1);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v);}assert_eq!(a,1);r(u)}
fn power(mut x:i64,mut n:i64)->i64{let mut o=1;while n>0{if n%2!=0{o=r(o*x)}x=r(x*x);n/=2}o}
fn add(p:P,q:P,a:i64)->P{match(p,q){(P::O,_)=>q,(_,P::O)=>p,(P::A(x,y),P::A(u,v))=>{if x==u&&r(y+v)==0{return P::O}let s=if x==u{r((3*x*x+a)*inv(2*y))}else{r((v-y)*inv(u-x))};let z=r(s*s-x-u);P::A(z,r(s*(x-z)-y))}}}
fn mul(mut p:P,mut n:i64,a:i64)->P{let mut q=P::O;while n>0{if n&1!=0{q=add(q,p,a)}p=add(p,p,a);n>>=1}q}
fn on(p:P,a:i64,b:i64)->bool{match p{P::O=>true,P::A(x,y)=>r(y*y)==r(x*x*x+a*x+b)}}
fn points(a:i64,b:i64)->Vec<P>{let mut v=vec![P::O];for x in 0..61{for y in 0..61{let p=P::A(x,y);if on(p,a,b){v.push(p)}}}v}
fn phi(p:P)->P{match p{P::O=>P::O,P::A(1,_)=>P::O,P::A(x,y)=>{let s=inv(x-1);P::A(r(x+24*s),r(y*(1-24*s*s)))}}}
fn dual(p:P)->P{match p{P::O=>P::O,P::A(59,_)=>P::O,P::A(x,y)=>{let s=inv(x-59);P::A(r(46*(x+35*s)),r(23*y*(1-35*s*s)))}}}
fn coord(p:P)->(i64,i64){match p{P::O=>(-1,-1),P::A(x,y)=>(x,y)}}
fn row(line:&str,kind:&str,id:usize,p:P,image:P,comp:P,round:P,odd:bool){let v:Vec<_>=line.split_whitespace().collect();assert_eq!(v.len(),11);assert_eq!(v[0],kind);let n:Vec<i64>=v[1..].iter().map(|x|x.parse().unwrap()).collect();let(x,y)=coord(p);let(a,b)=coord(image);let(c,d)=coord(comp);let(e,f)=coord(round);assert_eq!(n,vec![id as i64,x,y,a,b,c,d,e,f,odd as i64]);}
fn run(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),3);let s=fs::read_to_string(&a[1]).unwrap();let mut lines=s.lines();assert_eq!(lines.next(),Some("CM61 61 59 21 39 23 54 31 16 24 35 46 23"));let e=points(21,39);let t=points(23,54);assert_eq!((e.len(),t.len()),(62,62));assert_ne!(r(4*21*21*21+27*39*39),0);assert_ne!(r(4*23*23*23+27*54*54),0);assert!((0..61).all(|x|r(x*x)!=59));assert_eq!((r(59*59*21),r(power(59,3)*39)),(23,54));let g=*e.iter().find(|&&p|p!=P::O&&mul(p,31,21)==P::O).unwrap();let u=phi(g);assert_ne!(u,P::O);assert_eq!(mul(u,31,23),P::O);let(x,y)=coord(g);let(v,w)=coord(u);assert_eq!(lines.next().unwrap(),format!("GEN {} {} {} {}",x,y,v,w));
 let(mut es,mut ts,mut ek,mut tk)=(0,0,0,0);for(i,&p)in e.iter().enumerate(){let z=phi(p);assert!(on(z,23,54));let c=dual(z);assert_eq!(c,mul(p,2,21));let back=mul(c,16,21);let odd=mul(p,31,21)==P::O;if odd{assert_eq!(back,p);es+=1}ek+=usize::from(z==P::O);row(lines.next().unwrap(),"E",i,p,z,c,back,odd);}
 for(i,&p)in t.iter().enumerate(){let z=dual(p);assert!(on(z,21,39));let c=phi(z);assert_eq!(c,mul(p,2,23));let back=phi(mul(z,16,21));let odd=mul(p,31,23)==P::O;if odd{assert_eq!(back,p);ts+=1}tk+=usize::from(z==P::O);row(lines.next().unwrap(),"T",i,p,z,c,back,odd);}
 let(mut eh,mut th)=(0,0);for &p in &e{for &q in &e{assert_eq!(phi(add(p,q,21)),add(phi(p),phi(q),23));eh+=1;}}for &p in &t{for &q in &t{assert_eq!(dual(add(p,q,23)),add(dual(p),dual(q),21));th+=1;}}for n in 0..31{assert_eq!(phi(mul(g,n,21)),mul(u,n,23));}let scales=(1..61).filter(|&u|r(21*power(u,4))==23&&r(39*power(u,6))==54).count();assert_eq!((es,ts,ek,tk,scales),(31,31,2,2,0));assert_eq!(lines.next().unwrap(),format!("CHECK 62 62 {} {} 31 31 31 0 2 2",eh,th));let k=P::A(1,0);assert_ne!(k,P::O);assert_eq!(phi(k),P::O);assert_ne!(mul(k,31,21),P::O);assert_ne!(mul(dual(phi(k)),16,21),k);assert_eq!(lines.next(),Some("INJECTION 0"));assert!(lines.next().is_none());fs::write(&a[2],format!("{{\"source_points\":62,\"twist_points\":62,\"source_addition_pairs\":{},\"dual_addition_pairs\":{},\"odd_source_points\":31,\"odd_twist_points\":31,\"scalar_images\":31,\"short_scalings\":0,\"source_kernel\":2,\"dual_kernel\":2,\"P\":[{},{}],\"U\":[{},{}],\"global_injective\":false,\"solver_degree\":null}}\n",eh,th,x,y,v,w)).unwrap();}
fn main(){if std::panic::catch_unwind(run).is_err(){std::process::exit(101)}}
